import { test, expect } from '@playwright/test';

test.describe('Modal Responsive on Mobile Screen Sizes', () => {
  const MOBILE_VIEWPORT = { width: 375, height: 667 };
  const TABLET_VIEWPORT = { width: 768, height: 1024 };
  const DESKTOP_VIEWPORT = { width: 1920, height: 1080 };

  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <head>
          <style>
            * {
              margin: 0;
              padding: 0;
              box-sizing: border-box;
            }

            body {
              font-family: Arial, sans-serif;
              background-color: #f5f5f5;
              padding: 20px;
            }

            .modal-overlay {
              display: none;
              position: fixed;
              top: 0;
              left: 0;
              right: 0;
              bottom: 0;
              background-color: rgba(0, 0, 0, 0.5);
              z-index: 999;
              align-items: center;
              justify-content: center;
            }

            .modal-overlay.active {
              display: flex;
            }

            .modal-content {
              background-color: white;
              border-radius: 8px;
              box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
              width: 90%;
              max-width: 500px;
              max-height: 90vh;
              overflow-y: auto;
              padding: 24px;
              animation: slideUp 0.3s ease-out;
            }

            @keyframes slideUp {
              from {
                transform: translateY(100%);
                opacity: 0;
              }
              to {
                transform: translateY(0);
                opacity: 1;
              }
            }

            .modal-header {
              display: flex;
              justify-content: space-between;
              align-items: center;
              margin-bottom: 16px;
              padding-bottom: 12px;
              border-bottom: 1px solid #e0e0e0;
            }

            .modal-title {
              font-size: 20px;
              font-weight: 600;
              color: #333;
              margin: 0;
            }

            .modal-close-btn {
              background: none;
              border: none;
              font-size: 24px;
              cursor: pointer;
              color: #666;
              padding: 0;
              width: 32px;
              height: 32px;
              display: flex;
              align-items: center;
              justify-content: center;
            }

            .modal-close-btn:hover {
              color: #333;
            }

            .modal-body {
              margin: 16px 0;
              color: #555;
              line-height: 1.6;
            }

            .modal-footer {
              display: flex;
              gap: 12px;
              margin-top: 24px;
              padding-top: 16px;
              border-top: 1px solid #e0e0e0;
              flex-direction: row;
            }

            .modal-footer button {
              flex: 1;
              padding: 10px 16px;
              border: none;
              border-radius: 4px;
              cursor: pointer;
              font-size: 14px;
              font-weight: 500;
              transition: all 0.2s;
            }

            .modal-footer .btn-primary {
              background-color: #007bff;
              color: white;
            }

            .modal-footer .btn-primary:hover {
              background-color: #0056b3;
            }

            .modal-footer .btn-secondary {
              background-color: #e0e0e0;
              color: #333;
            }

            .modal-footer .btn-secondary:hover {
              background-color: #d0d0d0;
            }

            .open-modal-btn {
              padding: 12px 24px;
              background-color: #007bff;
              color: white;
              border: none;
              border-radius: 4px;
              cursor: pointer;
              font-size: 16px;
              font-weight: 500;
            }

            .open-modal-btn:hover {
              background-color: #0056b3;
            }

            @media (max-width: 480px) {
              .modal-content {
                width: 95%;
                padding: 16px;
                max-height: 95vh;
              }

              .modal-title {
                font-size: 18px;
              }

              .modal-footer {
                flex-direction: column;
              }

              .modal-footer button {
                width: 100%;
              }
            }

            @media (min-width: 481px) and (max-width: 768px) {
              .modal-content {
                width: 85%;
                max-width: 450px;
              }
            }
          </style>
        </head>
        <body>
          <button class="open-modal-btn" id="openModalBtn">Open Modal</button>

          <div class="modal-overlay" id="modalOverlay">
            <div class="modal-content" role="dialog" aria-labelledby="modalTitle" aria-modal="true">
              <div class="modal-header">
                <h2 class="modal-title" id="modalTitle">Modal Dialog</h2>
                <button class="modal-close-btn" id="closeModalBtn" aria-label="Close modal">&times;</button>
              </div>
              <div class="modal-body">
                <p>This is a responsive modal dialog that adapts to different screen sizes. On mobile devices, it takes up more of the screen width and stacks buttons vertically for better usability.</p>
              </div>
              <div class="modal-footer">
                <button class="btn-secondary" id="cancelBtn">Cancel</button>
                <button class="btn-primary" id="confirmBtn">Confirm</button>
              </div>
            </div>
          </div>

          <script>
            const openModalBtn = document.getElementById('openModalBtn');
            const closeModalBtn = document.getElementById('closeModalBtn');
            const cancelBtn = document.getElementById('cancelBtn');
            const confirmBtn = document.getElementById('confirmBtn');
            const modalOverlay = document.getElementById('modalOverlay');

            openModalBtn.addEventListener('click', () => {
              modalOverlay.classList.add('active');
            });

            closeModalBtn.addEventListener('click', () => {
              modalOverlay.classList.remove('active');
            });

            cancelBtn.addEventListener('click', () => {
              modalOverlay.classList.remove('active');
            });

            confirmBtn.addEventListener('click', () => {
              modalOverlay.classList.remove('active');
            });

            modalOverlay.addEventListener('click', (e) => {
              if (e.target === modalOverlay) {
                modalOverlay.classList.remove('active');
              }
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should display modal responsively on mobile screen size', async ({ page }) => {
    await page.setViewportSize(MOBILE_VIEWPORT);

    const openButton = page.getByRole('button', { name: 'Open Modal' });
    await openButton.click();

    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    const modalContent = page.locator('.modal-content');
    const boundingBox = await modalContent.boundingBox();

    expect(boundingBox).not.toBeNull();
